// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // accept ETH so the owner's transfer in the reference succeeds
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;
        vm.prank(c.owner());
        c.withdraw(amount);
        assertTrue(address(c).balance == before - amount);
    }
}
